// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * FUTUREWORK - Policy Gate (Dev 3).
 *
 * Only the critical release rules live on-chain. Heavy business logic (risk scoring, evidence
 * analysis) stays in the application services to limit gas and attack surface.
 *
 *   milestoneCompleted ┐
 *   evidenceValid      │
 *   clientApproved     ├─ all true ─► RELEASE ALLOWED (once per milestone key)
 *   conditionsSatisfied│
 *   riskAllowed        ┘
 *
 * `key` is keccak256("<projectId>:<milestoneId>"). A key can be released only once, which gives
 * on-chain idempotency on top of the database constraint.
 */
contract PolicyGate {
    address public immutable owner;
    mapping(bytes32 => bool) public released;

    event ReleaseAllowed(bytes32 indexed key, address indexed caller);
    /// @param failedMask bit 0 = milestoneCompleted ... bit 4 = riskAllowed; a set bit means the rule failed
    event ReleaseBlocked(bytes32 indexed key, uint8 failedMask);

    error NotOwner();
    error AlreadyReleased(bytes32 key);

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    /// Pure rule evaluation, free to call.
    function evaluate(
        bool milestoneCompleted,
        bool evidenceValid,
        bool clientApproved,
        bool conditionsSatisfied,
        bool riskAllowed
    ) public pure returns (bool allowed, uint8 failedMask) {
        if (!milestoneCompleted) failedMask |= 1;
        if (!evidenceValid) failedMask |= 2;
        if (!clientApproved) failedMask |= 4;
        if (!conditionsSatisfied) failedMask |= 8;
        if (!riskAllowed) failedMask |= 16;
        allowed = failedMask == 0;
    }

    /// Records the decision. Blocked attempts are logged (not reverted) so they stay auditable.
    function release(
        bytes32 key,
        bool milestoneCompleted,
        bool evidenceValid,
        bool clientApproved,
        bool conditionsSatisfied,
        bool riskAllowed
    ) external onlyOwner returns (bool) {
        if (released[key]) revert AlreadyReleased(key);
        (bool allowed, uint8 failedMask) = evaluate(
            milestoneCompleted, evidenceValid, clientApproved, conditionsSatisfied, riskAllowed
        );
        if (!allowed) {
            emit ReleaseBlocked(key, failedMask);
            return false;
        }
        released[key] = true;
        emit ReleaseAllowed(key, msg.sender);
        return true;
    }
}

